    public static int findNthLeapYear(int Y, int N) {
        int count = 0;
        int year = Y;

        while (count < N) {
            if (isLeapYear(year)) {
                count++;
            }
            year++;
        }

        return year - 1; // Subtract 1 to get the correct index
