import java.util.HashMap;
import java.util.Map;

public int findLargestSubstring(List<String> strings) {
    Map<String, Integer> lengthToMaxDistance = new HashMap<>();
    for (String str : strings) {
        for (int i = 1; i <= str.length(); i++) {
            lengthToMaxDistance.put(str.substring(0, i), i - 1);
        }
    }

    String maxSub = "";
    int maxLength = 0;
    for (String str : strings) {
        int length = str.length();
        Map<String, Integer> currentDistances = new HashMap<>();
        for (int i = length - 1; i >= 0; i--) {
            String reversedStr = new StringBuilder(str.substring(i)).reverse().toString();
            if (lengthToMaxDistance.containsKey(reversedStr)) {
                int distance = lengthToMaxDistance.get(reversedStr);
                currentDistances.put(str.substring(0, i + distance), distance);
            }
        }
        for (int key : currentDistances.values()) {
            if (key > maxLength) {
                maxLength = key;
                maxSub = str.substring(0, key + 1);
            }
        }
    }

    return maxLength;
}
