import java.util.HashSet;
import java.util.Set;

public class OilDepositsCount {

    public static int countOilDeposits(char[][] grid) {
        Set<String> visited = new HashSet<>();
        int count = 0;

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (!visited.contains(createKey(i, j)) && grid[i][j] == '@') {
                    dfs(grid, i, j, visited);
                    count++;
                }
            }
        }

        return count;
    }

    private static void dfs(char[][] grid, int row, int col, Set<String> visited) {
        if (row < 0 || col < 0 || row >= grid.length || col >= grid[row].length || grid[row][col] != '@') {
            return;
        }
        visited.add(createKey(row, col));
        dfs(grid, row + 1, col, visited);
        dfs(grid, row - 1, col, visited);
        dfs(grid, row, col + 1, visited);
        dfs(grid, row, col - 1, visited);
    }

    private static String createKey(int row, int col) {
        return row + "," + col;
    }

    public static void main(String[] args) {
        char[][] grid1 = {
            {'*'}
        };
        System.out.println(countOilDeposits(grid1)); // Output: 0

        char[][] grid2 = {
            {'*', '@', '*', '@', '*'},
            {'*', '*', '@', '*', '*'},
            {'*', '@', '*', '@', '*'}
        };
        System.out.println(countOilDeposits(grid2)); // Output: 1

        char[][] grid3 = {
            {'@', '@', '*', '*', '*', '@', '*', '*'}
        };
        System.out.println(countOilDeposits(grid3)); // Output: 2
    }
}
```

This solution defines the `countOilDeposits` method to traverse the grid and count the number of oil deposits using Depth-First Search (DFS). The `dfs` method marks visited cells to prevent revisiting them and ensures that each oil deposit is counted only once. The test cases in the `main` method demonstrate the functionality of the `countOilDeposits` method with different grid configurations.

