public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                count++;
                markUsed(grid, i, j);
            }
        }
    }
    return count;
}

private static void markUsed(char[][] grid, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[i].length || grid[i][j] != '@') {
        return;
    }
    grid[i][j] = '#';
    markUsed(grid, i - 1, j);
    markUsed(grid, i + 1, j);
    markUsed(grid, i, j - 1);
    markUsed(grid, i, j + 1);
}
