import java.util.HashSet;
import java.util.Set;

public class OilDepositCounter {

    /**
     * Counts the number of distinct oil deposits in a given grid.
     *
     * @param grid the grid representing the land
     * @return the number of distinct oil deposits
     */
    public static int countOilDeposits(char[][] grid) {
        Set<String> oilDeposits = new HashSet<>();
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '@') {
                    oilDeposits.add(getLocation(i, j, rows, cols));
                }
            }
        }

        return oilDeposits.size();
    }

    /**
     * Generates a unique location string based on the row, column indices.
     *
     * @param row the row index
     * @param col the column index
     * @param rows the number of rows in the grid
     * @param cols the number of columns in the grid
     * @return a unique location string
     */
    private static String getLocation(int row, int col, int rows, int cols) {
        if (row < 0 || row >= rows || col < 0 || col >= cols) {
            return "invalid";
        }
        return row + ":" + col;
    }
}
