public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int oilDeposits = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                bfs(grid, i, j, visited, oilDeposits);
            }
        }
    }

    return oilDeposits;
}

private static void bfs(char[][] grid, int x, int y, boolean[][] visited, int oilDeposits) {
    int dx[] = {-1, 0, 1, 0}; // Up, right, down, left
    int dy[] = {0, 1, 0, -1}; // Up, right, down, left

    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{x, y});
    visited[x][y] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int currentX = current[0];
        int currentY = current[1];

        oilDeposits++;

        for (int i = 0; i < 4; i++) {
            int nextX = currentX + dx[i];
            int nextY = currentY + dy[i];

            if (isWithinBounds(grid, nextX, nextY) && grid[nextX][nextY] == '@' && !visited[nextX][nextY]) {
                visited[nextX][nextY] = true;
                queue.add(new int[]{nextX, nextY});
            }
        }
    }
}

private static boolean isWithinBounds(char[][] grid, int x, int y) {
    return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
}
