public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int rows = n;
    int cols = n;

    boolean[][] visited = new boolean[rows][cols];
    visited[start[0]][start[1]] = true;

    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{start[0], start[1]});

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int row = current[0];
        int col = current[1];

        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] neighbor : findNeighbors(row, col, rows, cols)) {
            int newRow = neighbor[0];
            int newCol = neighbor[1];
            if (!visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                queue.add(new int[]{newRow, newCol});
            }
        }
    }

    return "cannot be travelled";
}

private static int[][] findNeighbors(int row, int col, int rows, int cols) {
    int[][] neighbors = new int[][]{
        {row - 1, col},
        {row + 1, col},
        {row, col - 1},
        {row, col + 1}
    };

    int[][] validNeighbors = new int[0][2];
    for (int[] neighbor : neighbors) {
        int newRow = neighbor[0];
        int newCol = neighbor[1];
        if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols) {
            validNeighbors = addToArray(validNeighbors, newRow, newCol);
        }
    }

    return validNeighbors;
}

private static int[][] addToArray(int[][] array, int row, int col) {
    int[][] result = new int[array.length + 1][2];
    for (int i = 0; i < array.length; i++) {
        result[i][0] = array[i][0];
        result[i][1] = array[i][1];
    }
    result[array.length][0] = row;
    result[array.length][1] = col;
    return result;
}
