private static String canTravelMazeRecursive(int n, int[] start, int[] end, int[][] paths, boolean[][] visited) {
    // Check if the start and end coordinates are within the bounds of the n-teresting space
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Mark the start coordinates as visited
    visited[start[0]][start[1]] = true;

    // If the start coordinates match the end coordinates, return "can be travelled"
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Check all four adjacent directions relative to the current coordinates
    for (int[] dir : new int[][]{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
        int newX = start[0] + dir[0];
        int newY = start[1] + dir[1];

        // Check if the new coordinates are within the bounds of the n-teresting space and not visited
        if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
            // Recursively check the next position
            if (canTravelMazeRecursive(n, new int[]{newX, newY}, end, paths, visited)) {
                return "can be travelled";
            }
        }
    }

    // If no valid path is found, return "cannot be travelled"
    return "cannot be travelled";
}
