public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null || paths.length == 0 || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean isValid = true;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            visited[i][j] = false;
        }
    }

    findPaths(n, 0, 0, start, end, visited, paths, isValid);
    return isValid ? "can be travelled" : "cannot be travelled";
}

private static void findPaths(int n, int i, int j, int[] start, int[] end, boolean[][] visited, int[][] paths, boolean isValid) {
    if (i < 0 || j < 0 || i >= n || j >= n || visited[i][j] || !isValid || paths[i][j] != 0) {
        isValid = false;
        return;
    }

    if (i == end[0] && j == end[1]) {
        return;
    }

    visited[i][j] = true;
    findPaths(n, i + 1, j, start, end, visited, paths, isValid);
    findPaths(n, i - 1, j, start, end, visited, paths, isValid);
    findPaths(n, i, j + 1, start, end, visited, paths, isValid);
    findPaths(n, i, j - 1, start, end, visited, paths, isValid);
}
