public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the start and end coordinates are within the valid range
    if (start[0] < 1 || start[0] > n || start[1] < 1 || start[1] > n || end[0] < 1 || end[0] > n || end[1] < 1 || end[1] > n) {
        return "cannot be travelled";
    }

    // Initialize a 2D array to store the status of each cell in the maze
    boolean[][] visited = new boolean[n + 1][n + 1];
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            visited[i][j] = false;
        }
    }

    // Mark the start cell as visited
    visited[start[0]][start[1]] = true;

    // Create a stack to perform the depth-first search
    Stack<int[]> stack = new Stack<>();
    stack.add(start);

    while (!stack.isEmpty()) {
        int[] current = stack.pop();
        int x = current[0];
        int y = current[1];

        // If the current cell is the end cell, the travel is possible
        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        // Explore all possible directions
        int[][] directions = new int[][]{{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int[] dir : directions) {
            int newX = x + dir[0];
            int newY = y + dir[1];

            // Check if the new cell is within the valid range and not visited
            if (newX >= 1 && newX <= n && newY >= 1 && newY <= n && !visited[newX][newY]) {
                // Mark the new cell as visited
                visited[newX][newY] = true;
                // Add the new cell to the stack
                stack.add(new int[]{newX, newY});
            }
        }
    }

    // If the travel is not possible, return "cannot be travelled"
    return "cannot be travelled";
}
