public static String appx(String word1, String word2) {
    // Count common letters
    int commonLettersCount = 0;
    for (int i = 0; i < word1.length() && i < word2.length(); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLettersCount++;
        }
    }

    // Calculate approximate value
    int numerator = commonLettersCount;
    int denominator = word1.length() + word2.length() - commonLettersCount;
    if (denominator == 0) {
        return "Error: Division by zero.";
    }

    // Simplify fraction
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    return String.format("appx(%s, %s) = %d/%d", word1, word2, numerator, denominator);
}

private static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}
