import java.time.DayOfWeek;

public static String convertDatesToWeekdays(String date) {
    // Split the input string into date components
    String[] parts = date.split("\\s+");
    if (parts.length != 3) {
        return "Invalid date format. Please provide date in MM dd yyyy format.";
    }

    try {
        // Parse the date components
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        // Create a Date object from the parsed date components
        java.util.Date dateObj = new java.util.Date(year, month - 1, day);

        // Get the weekday of the date
        DayOfWeek weekday = DayOfWeek.from(dateObj);

        // Format the weekday string
        String weekdayString = weekday.name();
        String monthString = month < 10 ? "0" + month : Integer.toString(month);
        String dayString = day < 10 ? "0" + day : Integer.toString(day);

        // Return the formatted weekday string
        return monthString + " " + dayString + ", " + year + " is a " + weekdayString;
    } catch (Exception e) {
        // Handle invalid date formats or other parsing errors
        return "Invalid date format. Please provide date in MM dd yyyy format.";
    }
}
