public class MinTime appleNode {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Build the adjacency list
        Map<Integer, List<Integer>> adj = new HashMap<>();
        for (int[] e : edges) {
            adj.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
            adj.computeIfAbsent(e[1], k -> new ArrayList<>()).add(e[0]);
        }

        // Define a recursive function to calculate the minimum time
        return dfs(adj, 0, hasApple, -1);
    }

    private int dfs(Map<Integer, List<Integer>> adj, int curr, boolean[] hasApple, int parent) {
        int totalTime = 0;
        for (int next : adj.getOrDefault(curr, Collections.emptyList())) {
            if (next != parent) {
                totalTime += dfs(adj, next, hasApple, curr);
                if (totalTime > 0 || hasApple[next]) {
                    totalTime += 2; // Time to go to the child node and return to the parent node
                }
            }
        }
        return totalTime;
    }
}
