        visited[node] = 1;

        for (int child : graph.get(node)) {
            if (visited[child] == 0) {
                dfs(graph, hasApple, child, time, visited);
                if (time[child] > 0 || hasApple[child]) {
                    time[node] += time[child] + 2;
                }
            }
        }
    }
