import java.util.*;

class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<List<Integer>> adjList = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adjList.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adjList.get(edge[0]).add(edge[1]);
            adjList.get(edge[1]).add(edge[0]);
        }

        return helper(n, adjList, hasApple, 0, 0);
    }

    private int helper(int n, List<List<Integer>> adjList, boolean[] hasApple, int node, int parent) {
        int time = 0;
        for (int neighbor : adjList.get(node)) {
            if (neighbor != parent) {
                time += helper(n, adjList, hasApple, neighbor, node);
            }
        }
        if (time == 0 && hasApple[node]) {
            time = 2;
        }
        if (time > 1) {
            time--;
        }
        return time;
    }
}
