public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    // Build the graph
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    return minTimeDFS(0, -1, hasApple, graph);
}

private int minTimeDFS(int node, int parent, boolean[] hasApple, List<List<Integer>> graph) {
    int totalTime = 0;
    for (int child : graph.get(node)) {
        if (child == parent) continue;
        int timeToLeaf = minTimeDFS(child, node, hasApple, graph);
        if (timeToLeaf > 0 || hasApple[child]) {
            totalTime += 2 + timeToLeaf;
        }
    }
    return totalTime;
}
