public String sortString(String s) {
    StringBuilder sortedString = new StringBuilder();
    int[] charCounts = new int[26]; // Array to count occurrences of each character in the string

    // Count occurrences of each character in the string
    for (char c : s.toCharArray()) {
        charCounts[c - 'a']++;
    }

    int min = 25;
    int max = 0;

    // Set initial indices for the smallest and largest characters
    for (int i = 0; i < 26; i++) {
        if (charCounts[i] > 0) {
            min = Math.min(min, i);
            max = Math.max(max, i);
        }
    }

    // Sort the string using the custom sorting algorithm
    while (true) {
        // Append the smallest character and decrement its count
        if (charCounts[min] > 0) {
            sortedString.append((char) (min + 'a'));
            charCounts[min]--;
        } else {
            int nextMin = min + 1;
            while (nextMin < 26 && charCounts[nextMin] == 0) {
                nextMin++;
            }
            if (nextMin == min + 1) {
                nextMin = -1;
            }
            min = nextMin;
        }

        if (min == -1) {
            break;
        }

        // Append the largest character and decrement its count
        if (charCounts[max] > 0) {
            sortedString.append((char) (max + 'a'));
            charCounts[max]--;
        } else {
            int nextMax = max - 1;
            while (nextMax >= 0 && charCounts[nextMax] == 0) {
                nextMax--;
            }
            if (nextMax == max - 1) {
                nextMax = -1;
            }
            max = nextMax;
        }

        if (max == -1) {
            break;
        }
    }

    return sortedString.toString();
}
