public boolean splitArraySameAverage(int[] nums) {
    int sum = Arrays.stream(nums).sum();
    if (sum == 0 || nums.length < 2) {
        return true;
    }
    double target = sum / (double) nums.length;
    int totalSum = Arrays.stream(nums).mapToInt(Integer::intValue).sum();
    boolean[] visited = new boolean[nums.length];
    return dfs(nums, target, totalSum, 0, visited, false);
}

private boolean dfs(int[] nums, double target, double totalSum, int start, boolean[] visited, boolean isFirstHalf) {
    if (start == nums.length) {
        return Math.abs(totalSum - (totalSum / 2)) < Double.EPSILON;
    }
    if (isFirstHalf && visited[start]) {
        return false;
    }
    if (!isFirstHalf && visited[start] || (totalSum / 2) < nums[start]) {
        return false;
    }
    visited[start] = true;
    return dfs(nums, target, (totalSum + nums[start]) / 2, start + 1, visited, false) || dfs(nums, target, totalSum / 2, start + 1, visited, true);
}
