public boolean splitArraySameAverage(int[] nums) {
    if (nums.length == 1) return false;
    int sum = Arrays.stream(nums).sum();
    if (sum % 2 != 0) return false;

    int average = sum / 2;
    int leftSum = 0;
    boolean[] seen = new boolean[nums.length];
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] == average || nums[i] == 0) {
            seen[i] = true;
            if (leftSum == average) return true;
        } else {
            leftSum += nums[i];
            if (!seen[i] && leftSum + nums[nums.length - 1] >= average) {
                seen[nums.length - 1] = true;
                if (leftSum > average) leftSum -= nums[nums.length - 1];
                if (leftSum == average) return true;
            }
        }
    }
    return false;
}
