public boolean hasAllCodes(String s, int k) {
    // Create a set to store all binary strings of length k
    HashSet<String> seen = new HashSet<>();

    // Loop through the string s with a step of k
    for (int i = 0; i <= s.length() - k; i++) {
        // Extract a substring of length k
        String substring = s.substring(i, i + k);
        // Add the substring to the set
        seen.add(substring);
    }

    // Check if the set size is equal to 2^(k-1)
    return seen.size() == (int)Math.pow(2, k - 1);
}
