public boolean hasAllCodes(String s, int k) {
    int totalPossibleCodes = 1 << k; // Total number of binary strings of length k
    int[] counts = new int[totalPossibleCodes]; // Array to count occurrences of each binary string
    int requiredLength = 0; // Length of all required binary strings

    // Compute the total possible length of all binary strings
    for (int i = 0; i < s.length(); i++) {
        requiredLength += k;
    }

    int charCount = 0;
    for (int i = 0; i < s.length(); i++) {
        counts[s.charAt(i) - '0']++; // Increment the count of the current bit
        charCount++;
        if (charCount == k) {
            requiredLength--; // Decrease the required length after processing a complete group of k bits
            charCount = 0;
        }
    }

    // Check if all required binary strings are present as substrings
    return requiredLength == 0; // If all required binary strings are present in s, return true
}
