public boolean hasAllCodes(String s, int k) {
    int need = (1 << k), cnt = 0;
    boolean[] visited = new boolean[need];
    int i = 0, j = 0;
    while (i < s.length()) {
        while (j < s.length() && j - i < k) {
            int lev = (s.charAt(j) - '0') << (k - j - 1);
            if (visited[lev]) break;
            visited[lev] = true;
            cnt++;
            j++;
        }
        if (cnt == need) break;
        i++;
        j = i;
    }
    return cnt == need;
}
