import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class PrefixChecker {

    /**
     * Checks if the searchWord is a prefix of any word in the sentence.
     *
     * @param sentence the sentence to search within
     * @param searchWord the word to search for as a prefix
     * @return the index of the first matching word, or -1 if not found
     */
    public static int isPrefixOfWord(String sentence, String searchWord) {
        Pattern pattern = Pattern.compile("\\b" + escapeRegex(searchWord) + "\\b");
        Matcher matcher = pattern.matcher(sentence);

        if (matcher.find()) {
            return matcher.start() + 1; // Match starts after word boundary
        }
        return -1;
    }

    /**
     * Escapes any regex special characters in the string.
     *
     * @param input the string to escape
     * @return the escaped string
     */
    private static String escapeRegex(String input) {
        return String.join("", input.chars().mapToObj(c -> "\\" + (char) c));
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(isPrefixOfWord("i love eating burger", "burg")); // Expected: 4
        System.out.println(isPrefixOfWord("this problem is an easy problem", "pro")); // Expected: 2
        System.out.println(isPrefixOfWord("i am tired", "you")); // Expected: -1
    }
}
