public int minInsertions(String s) {
    int open = 0, closeNeeded = 0, insertion = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else { // c == ')'
            afterOpen = !open.equals(0);
            if (!afterOpen)
                closeNeeded++;

            if (closeNeeded == 2)
                insertion++;
                closeNeeded = 0;
            if (open != 0)
