public int minInsertions(String s) {
    int left = 0;
    int right = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            left++;
            if (right > 0) {
                right--;
                insertions++;
            }
        } else {
            right++;
        }
    }

    // Calculate additional insertions needed to balance the left and right brackets
    inserted = left - insertions + right;

    return inserted;
}
