import java.util.Arrays;

public class Solution {
    /**
     * Calculates the highest altitude reached given the net gain in altitude between consecutive points.
     *
     * @param gain An array of integers representing the net gain in altitude between consecutive points.
     * @return The highest altitude reached.
     */
    public int highestAltitude(int[] gain) {
        int altitude = 0;
        int maxAltitude = 0;

        for (int level : gain) {
            altitude += level;
            maxAltitude = Math.max(maxAltitude, altitude);
        }

        return maxAltitude;
    }

