public int maxAbsoluteSum(int[] nums) {
    int minSum = 0, maxSum = 0, minElement = Integer.MAX_VALUE, maxElement = Integer.MIN_VALUE;

    for (int num : nums) {
        if (minSum > 0) {
            minSum = 0;
        }
        if (maxSum < 0) {
            maxSum = 0;
        }
        minSum += num;
        maxSum += num;
        minElement = Math.min(minElement, num);
        maxElement = Math.max(maxElement, num);
    }

    return Math.max(Math.abs(minElement), Math.abs(maxElement));
}
