public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    int maxVal = nums[0];
    int minVal = nums[0];
    int currMaxSum = nums[0];
    int currMinSum = nums[0];
    int leftMaxSum = 0;
    int rightMinSum = 0;

    for (int i = 1; i < nums.length; i++) {
        currMaxSum = Math.max(nums[i], currMaxSum + nums[i]);
        currMinSum = Math.min(nums[i], currMinSum + nums[i]);
        maxVal = Math.max(maxVal, currMaxSum);
        minVal = Math.min(minVal, currMinSum);
    }

    int upperBound = Math.max(0, maxVal);
    leftMaxSum = leftMaxAbs(nums, upperBound) - maxVal;
    rightMinSum = rightMaxAbs(nums, upperBound) - minVal;

    if (leftMaxSum < rightMinSum) {
      return rightMinSum;
    }

    upperBound = Math.min(0, minVal);
    leftMaxSum = leftMaxAbs(nums, upperBound) - maxVal;
    rightMinSum = rightMaxAbs(nums, upperBound) - minVal;

    // now check if leftMaxSum is minimized or rightMinSum is minimized
    if (leftMaxSum < rightMinSum) {
      return rightMinSum;
    } else {
      return leftMaxSum;
    }
}

private int leftMaxAbs(int[] nums, int bound) {
    int maxSoFar = nums[0];
    int currMax = nums[0];
    int leftMax = 0;

    for (int i = 1; i < nums.length; i++) {
        currMax = Math.max(nums[i], currMax + nums[i]);
        maxSoFar = Math.max(maxSoFar, currMax);

        // check if maxSoFar becomes negative, if yes, reset leftMax
        if (maxSoFar < 0) {
            leftMax = 0;
        }
    }
    return leftMax + bound;
}

private int rightMaxAbs(int[] nums, int bound) {
    int maxSoFar = nums[nums.length - 1];
    int currMax = nums[nums.length - 1];
    int rightMax = 0;

    for (int i = nums.length - 2; i >= 0; i--) {
        currMax = Math.max(nums[i], currMax + nums[i]);
        maxSoFar = Math.max(maxSoFar, currMax);

        // check if maxSoFar becomes negative, if yes, reset rightMax
        if (maxSoFar < 0) {
            rightMax = 0;
        }
    }
    return rightMax + bound;
}
