private static List<Integer> generateFibonacciSequence(int k) {
    List<Integer> fib = new ArrayList<>();
    fib.add(1);
    fib.add(1);
    int next = 2;
    while (next <= k) {
        fib.add(next);
        next = fib.get(fib.size() - 1) + fib.get(fib.size() - 2);
    }
    return fib;
}
