public int findMinFibonacciNumbers(int k) {
    if (k <= 2) return 1;

    int[] fib = new int[k + 1];
    fib[0] = 0;
    fib[1] = 1;

    for (int i = 2; i <= k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    int count = 0;
    int index = fib.length - 1;

    while (index >= 0 && k > 0) {
        if (k >= fib[index]) {
            k -= fib[index];
            count++;
        } else {
            index--;
        }
    }

    return count;
