import java.util.Scanner;

public class KthFactor {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        int n, k;

        System.out.print("Enter the first positive integer n: ");
        n = in.nextInt();
        System.out.print("Enter the positive integer k: ");
        k = in.nextInt();

        int result = kthFactor(n, k);

        if (result == -1) {
            System.out.println("No " + k + "-th factor of " + n);
        } else {
            System.out.println(k + "-th factor of " + n + " is: " + result);
        }

        in.close();
    }

    public static int kthFactor(int n, int k) {
        if (n < 1 || k < 1 || k > n) {
            return -1;
        }

        int factor = 2;
        int count = 0;

        while (factor * factor <= n) {
            if (n % factor == 0) {
                if (factor == n / factor) {
                    count++;
                } else {
                    count += 2;
                }
                if (count == k) {
                    return factor;
                }
            }
            factor++;
        }

        return -1;
    }
}
