        return s.length();
    }

    int result = 0;
    Set<String> uniqueSubstrings = new HashSet<>();

    for (int i = 1; i <= s.length(); i++) {
        String currentSubstr = s.substring(0, i);
        uniqueSubstrings.add(currentSubstr);

        if (uniqueSubstrings.size() == i) {
            result++;
            break;
        }

        for (int j = i; j < s.length(); j++) {
            currentSubstr += s.charAt(j);
            uniqueSubstrings.add(currentSubstr);

            if (uniqueSubstrings.size() == i + 1) {
                result++;
