public static double calculateProbability(int n) {
    if (n <= 2) {
        return 0.5;
    }
    double[][] dp = new double[n + 1][n + 1];
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= i; j++) {
            if (i == n && j == n) {
                dp[i][j] = 1;
            } else if (j == i + 1) {
                dp[i][j] = 1;
            } else {
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
            }
        }
    }
    return dp[n][0] / Math.pow(n, n);
}
