import java.util.ArrayList;
import java.util.List;

public class SteppingNumberFinder {
    /**
     * Finds all stepping numbers in the range [low, high].
     *
     * @param low The lower bound of the range.
     * @param high The upper bound of the range.
     * @return A list of stepping numbers within the range [low, high] sorted in ascending order.
     */
    public static List<Integer> findSteppingNumbers(int low, int high) {
        if (low > high) return new ArrayList<>();

        List<Integer> result = new ArrayList<>();
        int[] directions = {-1, 1};

        for (int i = 0; i <= 9; i++) {
            dfs(i + "", low, high, result, directions);
        }

        return result;
    }

    private static void dfs(String number, int low, int high, List<Integer> result, int[] directions) {
        int num = Integer.parseInt(number);
        if (num < low) return;
        if (num > high) return;

        result.add(num);

        for (int direction : directions) {
            if (validNumber(new StringBuilder(number).append(direction))) {
                dfs(number + direction, low, high, result, directions);
            }
        }
    }

    private static boolean validNumber(String number) {
        for (int i = 1; i < number.length(); i++) {
            int digit = Integer.parseInt(String.valueOf(number.charAt(i)));
            int prevDigit = Integer.parseInt(String.valueOf(number.charAt(i - 1)));
            if (Math.abs(prevDigit - digit) > 1) {
                return false;
            }
        }
        return true;
    }
}
