import java.util.Scanner;

public class CountDigitOne {

    /**
     * Calculates the number of times the digit 1 appears in all non-negative integers less than or equal to n.
     * 
     * @param n The upper limit.
     * @return The count of digit 1 appearances.
     */
    public static int countDigitOne(int n) {
        if (n == 0) {
            return 0;
        }

        long count = 0;
        for (int base = 1; base <= n; base *= 10) {
            int low = (n / base) * 10;
            int high = n % base;
            int current = n / base % 10;

            if (current == 0) {
                count += high + 1;
            } else if (current == 1) {
                count += high + 1 + (low / base);
            } else {
                count += low + 1 + (base - 1) * base;
            }
        }

        return (int) count;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter an integer: ");
        int n = scanner.nextInt();

        System.out.println("Number of times the digit 1 appears in " + n + " is " + countDigitOne(n));

        scanner.close();
    }
}
