public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Check horizontal lines
    for (int r = 0; r < m; r++) {
        int maxCount = 0;
        for (int c = 0; c < n; c++) {
            if (mat[r][c] == 1) {
                maxCount++;
            } else {
                maxLength = Math.max(maxLength, maxCount);
                maxCount = 0;
            }
        }
        maxLength = Math.max(maxLength, maxCount);
    }

    // Check vertical lines
    for (int c = 0; c < n; c++) {
        int maxCount = 0;
        for (int r = 0; r < m; r++) {
            if (mat[r][c] == 1) {
                maxCount++;
            } else {
                maxLength = Math.max(maxLength, maxCount);
                maxCount = 0;
            }
        }
        maxLength = Math.max(maxLength, maxCount);
    }

    // Check diagonal lines
    for (int r = 0; r < m; r++) {
        int maxCount = 0;
        for (int c = 0; c < n; c++) {
            if (r + c == m - 1 && mat[r][c] == 1) {
                maxCount++;
            } else {
                maxLength = Math.max(maxLength, maxCount);
                maxCount = 0;
            }
        }
        maxLength = Math.max(maxLength, maxCount);
    }

    // Check anti-diagonal lines
    for (int r = m - 1; r >= 0; r--) {
        int maxCount = 0;
        for (int c = 0; c < n; c++) {
            if (r - c == 0 && mat[r][c] == 1) {
                maxCount++;
            } else {
                maxLength = Math.max(maxLength, maxCount);
                maxCount = 0;
            }
        }
        maxLength = Math.max(maxLength, maxCount);
    }

    return maxLength;
}
