public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[][] dp = new int[2][cols];

    int maxCount = 0;

    // Fill the dp arrays for horizontal and vertical directions
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                dp[0][j] = j > 0 ? dp[0][j - 1] + 1 : 1;
                dp[1][j] = i > 0 ? dp[1][j] + 1 : 1;
            }
        }
    }

    // Horizontal and vertical dp arrays are computationally expensive,
    // and there are many cases where we do not need this. For this problem,
    // we only need to consider the uniqueness rule of diagonal and
    // anti-diagonal, which means there are only 4 possible directions.
    int curr_count = 1;
    int max_count = 1;
    int[] dp_diagonal = new int[4];
    int[] dp_anti_diagonal = new int[4];

    // Fill the dp array for diagonal and anti-diagonal directions
    for (int i = 1, j = 1; i < rows && j < cols; i++, j++) {
        if (mat[i][j] == 1) {
            dp_diagonal[0] = i > 0 ? dp_diagonal[0] + 1 : 1;
            dp_diagonal[1] = j > 0 ? dp_diagonal[1] + 1 : 1;
            curr_count = Math.max(curr_count, dp_diagonal[0] + dp_diagonal[1] - 1);

            dp_anti_diagonal[0] = i < rows - 1 ? dp_anti_diagonal[0] + 1 : 1;
            dp_anti_diagonal[1] = j < cols - 1 ? dp_anti_diagonal[1] + 1 : 1;
            curr_count = Math.max(curr_count, dp_anti_diagonal[0] + dp_anti_diagonal[1] - 1);
        } else {
            dp_diagonal = new int[4];
            dp_anti_diagonal = new int[4];
            curr_count = 1;
        }
        maxCount = Math.max(maxCount, curr_count);
    }

    return maxCount;
}
