private static int countLine(int[][] mat, int i, int j) {
    int len = 1;
    int m = mat.length;
    int n = mat[0].length;

    while (i + len < m && j + len < n && mat[i][j + len] == 1) {
        len++;
    }
    while (i - len >= 0 && j + len < n && mat[i - len][j + len] == 1) {
        len++;
    }
    while (i + len < m && j - len >= 0 && mat[i + len][j - len] == 1) {
        len++;
    }
    while (i - len >= 0 && j - len >= 0 && mat[i - len][j - len] == 1) {
        len++;
    }

    return len;
}
