public static String addThousandSeparator(int n) {
    String str = Integer.toString(n);
    if (str.length() <= 3) {
        return str;
    }

    int i = 0;
    StringBuilder result = new StringBuilder();

    while (i < str.length()) {
        result.insert(0, str.substring(i, Math.min(i + 3, str.length())));
        i += 3;
        if (i < str.length()) {
            result.insert(0, '.');
        }
    }

    return result.toString();
}
