import java.util.Arrays;

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        int n = A.length;
        // Initialize result to 1 if the array has only one element and it is a perfect square
        if (n == 1) return A[0] % 2 == 0 ? 1 : 0;

        // Initialize a 2D array to store counts of square permutations
        int[][] dp = new int[n][n + 1];
        Arrays.fill(dp[0], 1); // Base case: single element array

        for (int i = 1; i < n; i++) {
            for (int x = 1; x <= i; x++) {
                // Calculate the square of x and check if it divides A[i]
                if (A[i] % (x * x) == 0) {
                    int y = A[i] / (x * x);
                    dp[i][x] = (dp[i][x] + dp[i - 1][y]) % 1000000007;
                }
            }
        }

        int result = 0;
        for (int i = 1; i <= n; i++) {
            result = (result + dp[n - 1][i]) % 1000000007;
        }

        return result;
    }
}
