public static int squarePermutations(int[] A) {
    int n = A.length;
    int count = 0;
    for (int i = 0; i < n; i++) {
        int squareRoot = (int) Math.sqrt(A[i]);
        if (squareRoot * squareRoot == A[i] && i != 0 && i != n - 1) {
            int temp = A[i];
            A[i] = A[i - 1];
            A[i - 1] = temp;
            if (counts(A))
                count++;
        }
    }
    return count;
}

 private static boolean counts(int[] A) {
    for (int i = 0; i < A.length - 1; i++) {
        if (Math.sqrt(A[i]) != Math.sqrt(A[i + 1])) {
            return false;
        }
    }
    return true;
}
