import java.util.ArrayList;
import java.util.Collections;

class Solution {
    public static int squarePermutations(int[] A) {
        // Find next permutation of input
        if (!nextPerm(A))
            return 0;

        int count = 0;

        // Combinations
        for (int i = 0; i <= A.length - 1; i++) {
            for (int j = i + 1; j <= A.length - 1; j++) {
                if (AiSizes(i) == AjSizes(j)) {
                    count++;
                }
            }
        }

        return count;
    }

    // Get number of permutations possible for an input
    private static int AiSizes(int i) {
        int result = 1;
        for (int j = 0; j < i; j++) {
            result *= (A.length - j);
        }
       	return result;
    }

    // Check if we can find next permutation of input
    private static boolean nextPerm(int[] A) {
	    // Find index i from last, which is less than it's right child
        int i = A.length - 1;
        while (i > 0 && A[i - 1] >= A[i])
            i--;
        if (i <= 0) 
            return false;

        int j = A.length - 1;
        while (A[j] <= A[i - 1])
            j--;
        // Swap
        swapValues(A, i - 1, j);

        // Reverse from i to end
        int start = i, end = A.length - 1;
        while (start < end) {
            swapValues(A, start, end);
            start++;
            end--;
        }
        return true;
    }

    // Helper function for swapping two elements
    private static void swapValues(int[] A, int i, int j) {
        int tmp = A[i];
        A[i] = A[j];
        A[j] = tmp;
    }

}
