public static int squarePermutations(int[] A) {
    if (A.length == 0)
        return 0;

    int n = A.length;
    int count = 0;

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (isPerfectSquare(A[i] + A[j])) {
                boolean[] visited = new boolean[n];
                visited[i] = true;
                visited[j] = true;
                count += countPermutations(i, j, visited, A);
                visited[i] = false;
                visited[j] = false;
            }
        }
    }

    return count % (1000000007);
}

private static boolean isPerfectSquare(int num) {
    if (num < 0) {
        return false;
    }
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

private static int countPermutations(int start, int next, boolean[] visited, int[] A) {
    if (start == next) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!visited[i] && isPerfectSquare(A[start] + A[i])) {
            visited[i] = true;
            count += countPermutations(start + 1, next, visited, A) % (1000000007);
            visited[i] = false;
        }
    }

    return count;
}
