    for (int i = 0; i < n; i++) {
        while (stack != -1 && heights[i] < heights[heightWithPrevSmallerIndex[stack]]) {
            int end = i;
            int start = heightWithPrevSmallerIndex[stack];
            stack--;
            int width = end - start - 1;
            int height = heights[start];
            maxArea = Math.max(maxArea, width * height);
        }
        heightWithPrevSmallerIndex[++stack] = i;
    }

    while (stack != -1) {
        int end = n;
        int start = heightWithPrevSmallerIndex[stack];
        stack--;
        int width = end - start - 1;
        int height = heights[start];
        maxArea = Math.max(maxArea, width * height);
    }

    return maxArea;
}
