public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] leftSmallerIndices = new int[heights.length];
    int[] rightSmallerIndices = new int[heights.length];
    Stack<Integer> stack = new Stack<>();

    // Find the index of the smallest element to the left of each bar
    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            leftSmallerIndices[i] = -1;
        } else {
            leftSmallerIndices[i] = stack.peek();
        }
        stack.push(i);
    }

    // Clear the stack for the next step
    stack.clear();

    // Find the index of the smallest element to the right of each bar
    for (int i = heights.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            rightSmallerIndices[i] = heights.length;
        } else {
            rightSmallerIndices[i] = stack.peek();
        }
        stack.push(i);
    }

    // Calculate the area of the rectangle for each bar
    for (int i = 0; i < heights.length; i++) {
        int width = rightSmallerIndices[i] - leftSmallerIndices[i] - 1;
        int area = heights[i] * width;
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}
