        index++;

        // Change direction after reaching the edge of the matrix
        if ((order[0] == 0 && col == m - 1) || (order[0] == 1 && row == n - 1)) {
            order[0] = order[0] == 0 ? 1 : 0;
        }

        // Move to the next position in the direction of the current order
        row += order[0] == 0 ? 1 : 0;
        col += order[0] == 1 ? 0 : 1;
    }

    return result;
}
