private static String permute(String str, int index) {
    if (index == str.length()) {
        return str;
    }

    char temp = str.charAt(index);
    for (int i = index; i < str.length(); i++) {
        str = swap(str, i, index);
        String perm = permute(str, index + 1);
        str = swap(str, i, index);
        if (perm != null && perm.length() <= digits.length()) {
            return perm;
        }
    }

    return null;
}

private static String swap(String s, int i, int j) {
    char[] chars = s.toCharArray();
    char temp = chars[i];
    chars[i] = chars[j];
    chars[j] = temp;
    return new String(chars);
}

private static boolean permutationIsValid(String perm, String digits) {
    if (perm.length() != digits.length()) {
        return false;
    }

    for (int i = 0; i < perm.length(); i++) {
        for (int j = i + 1; j < perm.length(); j++) {
            if (perm.charAt(i) == perm.charAt(j)) {
                return false;
            }
        }
    }

    return true;
}
