public static int findSmallestInteger(int n) {
    if (n <= 9) { // If n is a single-digit number, it's its smallest rearrangment
        return n;
    }

    // Convert to string toDigitsList
    List<Integer> digitsList = new ArrayList<>();
    while (n > 0) {
        digitsList.add(n % 10);
        n /= 10;
    }

    // Sort the list in descending order
    Collections.sort(digitsList, Collections.reverseOrder());

    // Check if the last digit can be decreased by one (for example, 9 could be 8)
    for (int i = 0; i < digitsList.size() - 1; i++) {
        if (digitsList.get(i) < digitsList.get(i + 1) - 1) {
            int digitToDecrease = digitsList.get(i);
            int digitToReplace = digitsList.get(i + 1) - 1;

            // Create a clone of the list to avoid modifying the original list
            List<Integer> modifiedList = new ArrayList<>(digitsList);
            modifiedList.set(i, digitToReplace);
            modifiedList.set(i + 1, digitToDecrease + 1);

            // If the modified list is in ascending order, it's the smallest
            if (isMonotonicIncreasing(modifiedList)) {
                return fillInRestOfTheDigits(modifiedList);
            } else {
                // Try a smaller rearrangement by swapping the last two digits
                modifiedList.set(i, digitsList.get(i + 1));
                modifiedList.set(i + 1, digitsList.get(i));

                if (isMonotonicIncreasing(modifiedList)) {
                    return fillInRestOfTheDigits(modifiedList);
                }
            }
        }
    }

    // If no valid rearrangement is found, return -1
    return -1;
}

private static boolean isMonotonicIncreasing(List<Integer> list) {
    if (list == null || list.size() <= 1) return true;

    for (int i = 0; i < list.size() - 1; i++) {
        if (list.get(i) >= list.get(i + 1)) return false;
    }

    return true;
}

private static int fillInRestOfTheDigits(List<Integer> list) {
    int n = 0;
    for (int digit : list) {
        n = n * 10 + digit;
    }
    return n;
}
