import java.util.ArrayList;
import java.util.Collections;

public class CenterSymmetricNumbers {
    public static List<String> centerSymmetricNumbers(int n) {
        // Initialize the list to store center symmetric numbers
        List<String> centerSymmetricNumbers = new ArrayList<>();

        // Handle edge cases
        if (n <= 0) {
            return centerSymmetricNumbers; // Return empty list for non-positive lengths
        }

        // Calculate the middle index
        int middleIndex = n / 2;

        // Generate center symmetric numbers for even length
        if (n % 2 == 0) {
            for (int i = 0; i <= middleIndex; i++) {
                String leftPart = leftPermutation(Integer.toString(i));
                String rightPart = rightPermutation invertedRightPermutation(Integer.toString(middleIndex - i));
                centerSymmetricNumbers.add(leftPart + rightPart);
            }
        }
        // Generate center symmetric numbers for odd length
        else {
            int middleChar = Character.forDigit(middleIndex, 10);
            for (int i = middleIndex; i >= 0; i--) {
                String leftPart = leftPermutation(Integer.toString(i));
                if (i == middleIndex) {
                    // Handle the center character
                    centerSymmetricNumbers.add(leftPart + String.valueOf(middleChar) + leftPart);
                } else {
                    String rightPart = rightPermutation invertedRightPermutation(Integer.toString(middleIndex - i));
                    centerSymmetricNumbers.add(leftPart + rightPart);
                }
            }
        }

        return centerSymmetricNumbers;
    }

    // Helper method to generate permutations in lexicographical order
    private static String leftPermutation(String num) {
        List<String> permutations = permute(num);
        Collections.sort(permutations); // Sort to get lexicographical order
        return permutations.get(0);
    }

    // Helper method to generate permutations in lexicographical order
    private static String rightPermutation(String num) {
        List<String> permutations = permute(num);
        Collections.sort(permutations); // Sort to get lexicographical order
        return permutations.get(permutations.size() - 1);
    }

    // Helper method to invert a string
    private static String invertedRightPermutation(String num) {
        num = negate(num);
        return reverse(num);
    }

    // Helper method to get the negative of a string
    private static String negate(String num) {
        StringBuilder sb = new StringBuilder();
        for(int i = num.length() - 1; i >= 0; i--) {
            sb.append(String.valueOf(num.charAt(i)));
        }
        return sb.toString();
    }

    // Helper method to reverse a string
    private static String reverse(String num) {
        StringBuilder sb = new StringBuilder();
        for(int i = num.length() - 1; i >= 0; i--) {
            sb.append(String.valueOf(num.charAt(i)));
        }
        return sb.toString();
    }

    // Helper method to generate permutations of a given string
    private static List<String> permute(String str) {
        List<String> permutations = new ArrayList<>();
        permute("", str, permutations);
        return permutations;
    }

    // Helper method to recursively generate permutations
    private static void permute(String prefix, String remaining, List<String> permutations) {
        if(remaining.length() == 0) {
            permutations.add(prefix);
            return;
        }
        for(int i = 0; i < remaining.length(); i++) {
            String newPrefix = prefix + remaining.charAt(i);
            String newRemaining = remaining.substring(0, i) + remaining.substring(i + 1);
            permute(newPrefix, newRemaining, permutations);
        }
    }
}
