public class CenterSymmetricNumbers {

    public static List<String> centerSymmetricNumbers(int n) {
        List<String> centerSymmetricNumbers = new ArrayList<>();
        if (n == 0) {
            centerSymmetricNumbers.add("");
        } else {
            for (int i = 0; i < (2 * sqrt(n) + 1); i++) {
                StringBuilder sb = new StringBuilder();
                int mid = n / 2;
                for (int j = 0; j <= i; j++) {
                    if (j <= mid) {
                        sb.append(Integer.toString(centerSymmetricNumbers.get(i-j).charAt(j)));
                    } else {
                        sb.append(Integer.toString(centerSymmetricNumbers.get(i-j).charAt(n-j")));
                    }
                }
                centerSymmetricNumbers.add(sb.toString());
            }
        }
        return centerSymmetricNumbers;
    }

    private static double sqrt(int n) {
        double x = n;
        double y = 1.0;
        while (y > x / y) {
            x = (y + x / y) / 2.0;
            y = 2.0 * x;
        }
        return x;
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: [11, 69, 88, 96]
        System.out.println(centerSymmetricNumbers(1)); // Output: [0, 1, 8]
    }
