    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    PriorityQueue<Long> heap = new PriorityQueue<>();
    heap.offer(1L); // Starting from the first ugly number, 1
    long visited[] = new long[n]; // Track visited numbers to avoid duplicates
    visited[0] = 1L;
    long idx = 0; // Index to keep track of the current position in the result array
    long[] result = new long[n];

    while (idx < n) {
        long curr = heap.poll();
        result[idx++] = (int) curr; // Add the current ugly number to the result

        // Generate new ugly numbers by multiplying the current ugly number with 2, 3, 5
        if (curr * 2 > 1L * visited[idx - 1]) {
            heap.offer(curr * 2);
            visited[idx] = curr * 2;
        }
        if (curr * 3 > 1L * visited[idx - 1]) {
            heap.offer(curr * 3);
            visited[idx] = curr * 3;
        }
        if (curr * 5 > 1L * visited[idx - 1]) {
            heap.offer(curr * 5);
            visited[idx] = curr * 5;
        }
    }

    return (int) result[n - 1];
