        result.add(i);
    }
    Collections.sort(result, (a, b) -> Integer.compare(a, b));
    return result;
}
```
The solution simply generates a list of integers from `1` to `n` and then sorts the list in lexicographical order.

```java
import java.util.ArrayList;
import java.util.Iterator;
import java.util.TreeSet;

public class LexicalOrder {
    private TreeSet<String> set = new TreeSet<>();

    public static void main(String[] args) {
        LexicalOrder orderer = new LexicalOrder();
        System.out.println(orderer.lexicalOrder(13)); // Output: [1,10,11,12,13,2,3,4,5,6,7,8,9]
    }

    public List<Integer> lexicalOrder(int n) {
        populateSet(1, n);
        List<Integer> resultList = new ArrayList<>();
        Iterator<String> iterator = set.iterator();
        while (iterator.hasNext()) {
            resultList.add(Integer.valueOf(iterator.next()));
        }
        return resultList;
    }

    private void populateSet(int start, int end) {
        if (start > end)
            return;
        String number = Integer.toString(start);
        set.add(number);
        if (start < end) {
            populateSet(start * 10, end);
            populateSet(start + 1, end);
        }
    }
}
