public static int minPerfectSquareSum(int n) {
    // Handle the base case of 0, which requires 0 perfect squares.
    if (n == 0) return 0;
    // Handle the base case of 1, which requires 1 perfect square (1 itself).
    if (n == 1) return 1;

    // Array to store the minimum number of perfect squares for each number up to n.
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 1;

    // Iterate through each number from 2 to n.
    for (int i = 2; i <= n; i++) {
        // Initialize with the current number.
        dp[i] = i;
        // Iterate through all perfect squares less than or equal to i.
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // Return the minimum number of perfect squares for the target integer n.
    return dp[n];
}
